IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_MEDIA') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_MEDIA varchar(10) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_ETAT_EMISSION') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_ETAT_EMISSION varchar(5) NULL;
