IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_NOMBRE_EXEMPLAIRE') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_NOMBRE_EXEMPLAIRE smallint NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_IMPRESSION') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_IMPRESSION bit NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_PAPIER_TRAME') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_PAPIER_TRAME bit NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_AGRAFAGE') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_AGRAFAGE bit NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_RECTO_VERSO') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_RECTO_VERSO bit NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_TYPE_GENERATION') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_TYPE_GENERATION varchar(32) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_AFF_AVANT_IMPRESSION') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_AFF_AVANT_IMPRESSION bit NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_INTERLOCUTEUR') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_INTERLOCUTEUR varchar(32) NULL;
