-- Les colonnes que le repertoire general recopie de son reglage d'edition (EcrivainRegistresJudiciaires.cs, en tete), aux types de
-- RIG_DEV (SSDT DEMANDE_EDITION.sql:3, :48, :65, :70).
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_CODE_PROCESSUS') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_CODE_PROCESSUS varchar(40) NULL;
