-- Le reglage d'edition du repertoire general (REP_GENERAL) : les colonnes lues, aux types de RIG_DEV (SSDT PARAMETRE_EDITION.sql).
IF OBJECT_ID(N'v2.PARAMETRE_EDITION') IS NULL
    CREATE TABLE v2.PARAMETRE_EDITION (PRMED_CODE varchar(40) NOT NULL PRIMARY KEY, PRMED_LIBELLE varchar(100) NOT NULL,
        PRMED_LISTE varchar(4000) NOT NULL, PRMED_CODE_ENTITE_SOURCE varchar(16) NULL, PRMED_CODE_PROCESSUS varchar(40) NULL,
        PRMED_CODE_MAQUETTE varchar(40) NULL, PRMED_TYPE_GENERATION varchar(15) NULL, PRMED_NOMBRE_EXEMPLAIRES int NOT NULL,
        PRMED_READ_ONLY bit NOT NULL, PRMED_NUM_GROUPE_IMPRESSION varchar(30) NULL, PRMED_CODE_CFECP varchar(50) NULL,
        PRMED_TRIBUNAL_DIGITAL_NATURE_DOC varchar(50) NULL);
-- fix-ok: mesure le 26/11/2026 sur la copie de dev (serveur 5096, journal : erreur 515 « Cannot insert the value NULL into column
-- 'DMNED_HAS_NUMLRAR' ») : la base V3 garde les colonnes NOT NULL de RIG_DEV mais PAS leurs valeurs par defaut ((0)). Ces
-- colonnes sont donc posees ici NOT NULL SANS defaut (le defaut ne sert qu'a remplir les lignes deja la, puis il est retire),
-- comme dans la base V3 : un ecrivain qui les oublie echoue au banc comme sur la base.
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_HAS_NUMLRAR') IS NULL
BEGIN
    ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_HAS_NUMLRAR bit NOT NULL CONSTRAINT DF_BancRegjud_HasNumLrar DEFAULT 0 WITH VALUES,
        DMNED_IS_NON_SUPPRESSIBLE bit NOT NULL CONSTRAINT DF_BancRegjud_NonSuppr DEFAULT 0 WITH VALUES,
        DMNED_HAS_NUMLR bit NOT NULL CONSTRAINT DF_BancRegjud_HasNumLr DEFAULT 0 WITH VALUES,
        DMNED_MASQUER_COFFRE_FORT bit NOT NULL CONSTRAINT DF_BancRegjud_Masquer DEFAULT 0 WITH VALUES;
    ALTER TABLE v2.DEMANDE_EDITION DROP CONSTRAINT DF_BancRegjud_HasNumLrar, DF_BancRegjud_NonSuppr, DF_BancRegjud_HasNumLr, DF_BancRegjud_Masquer;
END
